// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 initialBalance, uint256 extraDeposit) public {
        vm.assume(initialBalance >= 1 ether && initialBalance <= 1000 ether);
        vm.assume(extraDeposit <= 100 ether);

        address depositor = makeAddr("depositor");
        vm.deal(depositor, initialBalance);
        vm.prank(depositor);
        (bool ok,) = address(c).call{value: initialBalance}("");
        require(ok, "initial deposit failed");

        vm.deal(depositor, extraDeposit);
        vm.prank(depositor);
        (bool ok2,) = address(c).call{value: extraDeposit}("");
        require(ok2, "extra deposit failed");

        uint256 balanceBefore = address(c).balance;

        vm.prank(c.owner());
        try c.withdrawAll() {
            assertTrue(address(c).balance < balanceBefore);
        } catch {
            assertTrue(true);
        }
    }
}
